//! 🖊️ Admitted native Drawing fields, closed path commands and recursively bounded scene nodes.
use crate::standards::v1::subsets::base::schema::geometry::{SemioPoint3,SemioQuaternion,SemioTransform,SemioRgba};
use crate::standards::v1::subsets::drawing::schema::snapshot::{SemioDrawingSnapshot,DrawCanvas,DrawStyle,DrawLayer,DrawNode,PathSegment,SemioPoint2,STDIO_SEMIODRAWING_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::io::sqlite::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use semio_framework_value::{ValueError,ValueRefusalKind};
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(crate) fn decode(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>,native_control:&mut semio_framework_value::NativeDecodeControl<'_>)->Result<SemioDrawingSnapshot,ValueError>{
 let limits=control.limits();crate::standards::v1::subsets::drawing::io::sqlite::snapshot::admit_layout(limits)?;
 let size=match payload{store::io::IoPayload::Binary(value)=>value.len(),store::io::IoPayload::Text(value)=>value.len()};if size>limits.max_file_bytes{return Err(ValueError::new(ValueRefusalKind::OwnershipLimit,"Semio Drawing native input exceeds file limit"))}
 control.allocation_stage_native(store::sqlite_snapshot::SqliteSnapshotPhase::DecodeNative,|remaining,checkpoint|{
  let native_before=native_control.owned_bytes();let result=native_control.scoped_maximum(native_before.checked_add(remaining).ok_or_else(||ValueError::new(ValueRefusalKind::OwnershipLimit,"native snapshot allowance overflow"))?,|native_control|{
  let result=(||->Result<SemioDrawingSnapshot,ValueError>{let result=match payload{
   store::io::IoPayload::Binary(value)=>{let body=store::semio_format::unwrap_binary_controlled(value,STDIO_SEMIODRAWING_DOCUMENT_SCHEMA,store::semio_format::Component::Pack,1,native_control)?;binary(body,native_control,limits)?},
   store::io::IoPayload::Text(value)=>{let body=store::semio_format::split_text_preamble_controlled(value,STDIO_SEMIODRAWING_DOCUMENT_SCHEMA,store::semio_format::Component::Dsl,1,native_control).map_err(store::semio_format::SemioError::into_value_error)?;document(body,native_control,limits)?}
  };let result=native::Owned::new(result);native_control.checkpoint()?;Ok(result.take())})();result});(result,native_control.owned_bytes().saturating_sub(native_before))
 })?
}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,ValueError>{reader.read_f64_le().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))}
fn f32(reader:&mut store::ByteReader<'_>)->Result<f32,ValueError>{let bytes=reader.read_bytes(4).map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?;Ok(f32::from_le_bytes(bytes.try_into().map_err(|_|ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing binary32"))?))}
fn point2(reader:&mut store::ByteReader<'_>)->Result<SemioPoint2,ValueError>{Ok(SemioPoint2{x:f64(reader)?,y:f64(reader)?})}
fn point3(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,ValueError>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn transform(reader:&mut store::ByteReader<'_>)->Result<SemioTransform,ValueError>{Ok(SemioTransform{translation:point3(reader)?,rotation:SemioQuaternion{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?,w:f64(reader)?},scale:point3(reader)?})}
fn rgba(reader:&mut store::ByteReader<'_>)->Result<SemioRgba,ValueError>{Ok(SemioRgba{r:f32(reader)?,g:f32(reader)?,b:f32(reader)?,a:f32(reader)?})}
fn boolean(value:u8)->Result<bool,ValueError>{match value{0=>Ok(false),1=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native boolean"))}}
fn option<T>(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&mut store::ByteReader<'_>,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Option<T>,ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(None),1=>read(reader,control).map(Some),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}}
fn segment_binary(reader:&mut store::ByteReader<'_>,entities:&mut usize,limits:SqliteDatabaseLimits)->Result<PathSegment,ValueError>{native::entities(entities,1,limits)?;Ok(match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>PathSegment::MoveTo{to:point2(reader)?},1=>PathSegment::LineTo{to:point2(reader)?},2=>PathSegment::CubicTo{c1:point2(reader)?,c2:point2(reader)?,to:point2(reader)?},3=>PathSegment::QuadTo{c:point2(reader)?,to:point2(reader)?},4=>PathSegment::ArcTo{rx:f64(reader)?,ry:f64(reader)?,x_rotation:f64(reader)?,large_arc:boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?,sweep:boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?,to:point2(reader)?},5=>PathSegment::Close,_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native path command"))})}
fn node_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DrawNode,ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;Ok(match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{
0=>{let segments=native::binary_list(reader,control,limits,entities,|reader,_,entities|segment_binary(reader,entities,limits))?;let mut owner=native::Owned::new(DrawNode::Path{segments,style:None});let style=option(reader,control,native::text)?;if let DrawNode::Path{style:target,..}=owner.get_mut(){*target=style;}owner.take()},
1=>{let value=native::text(reader,control)?;let mut owner=native::Owned::new(DrawNode::Text{value,at:SemioPoint2{x:0.,y:0.},style:None});let at=point2(reader)?;let style=option(reader,control,native::text)?;if let DrawNode::Text{at:target,style:target_style,..}=owner.get_mut(){*target=at;*target_style=style;}owner.take()},
2=>{let transform=transform(reader)?;let children=native::binary_list(reader,control,limits,entities,|reader,control,entities|node_binary(reader,control,limits,entities))?;DrawNode::Group{transform,children}},
3=>{let at=point2(reader)?;let width=f64(reader)?;let height=f64(reader)?;let mime=native::text(reader,control)?;let mut owner=native::Owned::new(DrawNode::Image{at,width,height,mime,bytes:Vec::new()});let bytes=control.copy_bytes(native::bytes(reader)?)?;if let DrawNode::Image{bytes:target,..}=owner.get_mut(){*target=bytes;}owner.take()},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native scene node"))})})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDrawingSnapshot,ValueError>{crate::standards::v1::subsets::drawing::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Drawing native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;let mut owner=native::Owned::new(SemioDrawingSnapshot{schema,canvas:DrawCanvas{width:0.,height:0.,background:None},styles:Vec::new(),layers:Vec::new()});owner.get_mut().canvas=DrawCanvas{width:f64(&mut reader)?,height:f64(&mut reader)?,background:option(&mut reader,control,|reader,_|rgba(reader))?};owner.get_mut().styles=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|{let name=native::text(reader,control)?;let mut owner=native::Owned::new(DrawStyle{name,fill:None,stroke:None,stroke_width:None,opacity:None});owner.get_mut().fill=option(reader,control,|reader,_|rgba(reader))?;owner.get_mut().stroke=option(reader,control,|reader,_|rgba(reader))?;owner.get_mut().stroke_width=option(reader,control,|reader,_|f64(reader))?;owner.get_mut().opacity=option(reader,control,|reader,_|f32(reader))?;Ok(owner.take())})?;owner.get_mut().layers=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{let id=native::text(reader,control)?;let mut owner=native::Owned::new(DrawLayer{id,name:String::new(),visible:false,root:DrawNode::Path{segments:Vec::new(),style:None}});owner.get_mut().name=native::text(reader,control)?;owner.get_mut().visible=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;owner.get_mut().root=node_binary(reader,control,limits,entities)?;Ok(owner.take())})?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native trailing bytes"))}Ok(owner.take())}
fn bool_text(value:&str)->Result<bool,ValueError>{match value{"0"=>Ok(false),"1"=>Ok(true),_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native boolean"))}}
fn optional_text<T>(value:&str,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&str,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<Option<T>,ValueError>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}read(value,control).map(Some)}
fn point2_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint2,ValueError>{let[x,y]=native::record(value,control)?;Ok(SemioPoint2{x:native::float(x,control)?,y:native::float(y,control)?})}
fn point3_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,ValueError>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
fn transform_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioTransform,ValueError>{let[translation,rotation,scale]=native::record(value,control)?;let[x,y,z,w]=native::record(rotation,control)?;let rotation=SemioQuaternion{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?,w:native::float(w,control)?};Ok(SemioTransform{translation:point3_text(translation,control)?,rotation,scale:point3_text(scale,control)?})}
fn rgba_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioRgba,ValueError>{let[r,g,b,a]=native::record(value,control)?;Ok(SemioRgba{r:native::float32(r,control)?,g:native::float32(g,control)?,b:native::float32(b,control)?,a:native::float32(a,control)?})}
fn segment_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<PathSegment,ValueError>{native::entities(entities,1,limits)?;if value=="Z"{return Ok(PathSegment::Close)}let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native path tag missing"))?;Ok(match tag{"M"=>{let[to]=native::record(value,control)?;PathSegment::MoveTo{to:point2_text(to,control)?}},"L"=>{let[to]=native::record(value,control)?;PathSegment::LineTo{to:point2_text(to,control)?}},"C"=>{let[c1,c2,to]=native::record(value,control)?;PathSegment::CubicTo{c1:point2_text(c1,control)?,c2:point2_text(c2,control)?,to:point2_text(to,control)?}},"Q"=>{let[c,to]=native::record(value,control)?;PathSegment::QuadTo{c:point2_text(c,control)?,to:point2_text(to,control)?}},"A"=>{let[rx,ry,x_rotation,large_arc,sweep,to]=native::record(value,control)?;PathSegment::ArcTo{rx:native::float(rx,control)?,ry:native::float(ry,control)?,x_rotation:native::float(x_rotation,control)?,large_arc:bool_text(large_arc)?,sweep:bool_text(sweep)?,to:point2_text(to,control)?}},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native path command"))})}
fn node_text(value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<DrawNode,ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native scene tag missing"))?;Ok(match tag{
"P"=>{let[segments,style]=native::record(value,control)?;let segments=native::text_list(segments,control,limits,entities,|value,control,entities|segment_text(value,control,limits,entities))?;let mut owner=native::Owned::new(DrawNode::Path{segments,style:None});let style=optional_text(style,control,native::hex_text)?;if let DrawNode::Path{style:target,..}=owner.get_mut(){*target=style;}owner.take()},
"T"=>{let[value,at,style]=native::record(value,control)?;let value=native::hex_text(value,control)?;let mut owner=native::Owned::new(DrawNode::Text{value,at:SemioPoint2{x:0.,y:0.},style:None});let at=point2_text(at,control)?;let style=optional_text(style,control,native::hex_text)?;if let DrawNode::Text{at:target,style:target_style,..}=owner.get_mut(){*target=at;*target_style=style;}owner.take()},
"G"=>{let[transform,children]=native::record(value,control)?;let transform=transform_text(transform,control)?;let children=native::text_list(children,control,limits,entities,|value,control,entities|node_text(value,control,limits,entities))?;DrawNode::Group{transform,children}},
"I"=>{let[at,width,height,mime,bytes]=native::record(value,control)?;let at=point2_text(at,control)?;let width=native::float(width,control)?;let height=native::float(height,control)?;let mime=native::hex_text(mime,control)?;let mut owner=native::Owned::new(DrawNode::Image{at,width,height,mime,bytes:Vec::new()});let bytes=native::hex(bytes,control)?;if let DrawNode::Image{bytes:target,..}=owner.get_mut(){*target=bytes;}owner.take()},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native scene node"))})})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioDrawingSnapshot,ValueError>{crate::standards::v1::subsets::drawing::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","canvas","styles","layers"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::hex_text(fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native schema missing"))?,control)?;let mut owner=native::Owned::new(SemioDrawingSnapshot{schema,canvas:DrawCanvas{width:0.,height:0.,background:None},styles:Vec::new(),layers:Vec::new()});let[width,height,background]=native::record(fields[1].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native canvas missing"))?,control)?;owner.get_mut().canvas=DrawCanvas{width:native::float(width,control)?,height:native::float(height,control)?,background:optional_text(background,control,rgba_text)?};owner.get_mut().styles=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[name,fill,stroke,stroke_width,opacity]=native::record(value,control)?;let name=native::hex_text(name,control)?;let mut owner=native::Owned::new(DrawStyle{name,fill:None,stroke:None,stroke_width:None,opacity:None});owner.get_mut().fill=optional_text(fill,control,rgba_text)?;owner.get_mut().stroke=optional_text(stroke,control,rgba_text)?;owner.get_mut().stroke_width=optional_text(stroke_width,control,native::float)?;owner.get_mut().opacity=optional_text(opacity,control,native::float32)?;Ok(owner.take())})?;owner.get_mut().layers=native::text_list(fields[3].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{let[id,name,visible,root]=native::record(value,control)?;let id=native::hex_text(id,control)?;let mut owner=native::Owned::new(DrawLayer{id,name:String::new(),visible:false,root:DrawNode::Path{segments:Vec::new(),style:None}});owner.get_mut().name=native::hex_text(name,control)?;owner.get_mut().visible=bool_text(visible)?;owner.get_mut().root=node_text(root,control,limits,entities)?;Ok(owner.take())})?;Ok(owner.take())}
